package vn.riveriq.android;

import android.app.Activity;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import java.util.*;
import vn.riveriq.*;

public final class MainActivity extends Activity {
    RiverView view;
    public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xff0c4565);getWindow().setNavigationBarColor(0xff082b43);view=new RiverView(this);setContentView(view);}
    public void onBackPressed(){if(view.home)super.onBackPressed();else{view.home=true;view.invalidate();}}

    static final class RiverView extends View {
        static final float W=1280,H=760;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);final List<Puzzle> levels=PuzzleCatalog.all();final RectF[] people=new RectF[16],cards=new RectF[10];final SharedPreferences prefs;
        GameState game;int level;boolean home=true;float scale,left,top;final RectF move=new RectF(530,626,750,696),undo=new RectF(900,670,1000,714),reset=new RectF(1014,670,1114,714),hint=new RectF(1128,670,1248,714),back=new RectF(30,26,148,72);
        RiverView(Context c){super(c);prefs=c.getSharedPreferences("river_iq",Context.MODE_PRIVATE);setFocusable(true);setContentDescription("Qua Sông IQ. Chọn nhân vật và đưa thuyền qua sông.");}
        int unlocked(){return prefs.getInt("unlocked",1);}
        protected void onDraw(Canvas raw){super.onDraw(raw);raw.drawColor(0xff082b43);float aw=getWidth()-getPaddingLeft()-getPaddingRight(),ah=getHeight()-getPaddingTop()-getPaddingBottom();scale=Math.min(aw/W,ah/H);left=getPaddingLeft()+(aw-W*scale)/2;top=getPaddingTop()+(ah-H*scale)/2;raw.save();raw.translate(left,top);raw.scale(scale,scale);if(home)drawHome(raw);else drawGame(raw);raw.restore();postInvalidateDelayed(40);}
        public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;float x=(e.getX()-left)/scale,y=(e.getY()-top)/scale;if(home){for(int i=0;i<levels.size();i++)if(cards[i]!=null&&cards[i].contains(x,y)&&i<unlocked()){level=i;game=new GameState(levels.get(i));home=false;break;}}else if(back.contains(x,y)){home=true;}else if(game.won){if(new RectF(500,545,780,605).contains(x,y)){if(level+1<levels.size()){level++;game=new GameState(levels.get(level));}else home=true;}}else{boolean hit=false;for(int i=0;i<game.puzzle.people.length;i++)if(people[i]!=null&&people[i].contains(x,y)){game.toggle(i);hit=true;break;}if(!hit&&move.contains(x,y)){if(game.move()&&game.won){int best=prefs.getInt("best."+level,0);SharedPreferences.Editor ed=prefs.edit().putInt("unlocked",Math.max(unlocked(),level+2));if(best==0||game.moves<best)ed.putInt("best."+level,game.moves);ed.apply();}}else if(!hit&&undo.contains(x,y))game.undo();else if(!hit&&reset.contains(x,y))game.reset();else if(!hit&&hint.contains(x,y)){List<Integer> path=Solver.solve(game.puzzle,game.rightMask,game.boatRight);if(path.isEmpty())game.message="Hãy hoàn tác để tìm đường khác";else{game.selected=path.get(0);game.message="Đã chọn gợi ý cho chuyến kế tiếp";}}}performClick();invalidate();return true;}
        public boolean performClick(){super.performClick();return true;}
        void drawHome(Canvas c){gradient(c,0,0,W,H,0xff071b33,0xff0b4a69);p.setColor(0xfffff0b8);c.drawCircle(1080,86,58,p);text(c,"QUA SÔNG IQ",640,86,48,0xffeaf9ff,true,true);text(c,"Mỗi chuyến thuyền là một bài toán — bạn có thể giải hết 6 màn?",640,125,18,0xffa9dce8,false,true);int cw=350,ch=205,gap=24,sx=91,sy=158;
            for(int i=0;i<levels.size();i++){int col=i%3,row=i/3,x=sx+col*(cw+gap),y=sy+row*(ch+gap);cards[i]=new RectF(x,y,x+cw,y+ch);boolean open=i<unlocked();round(c,cards[i],24,open?0xfff8fcfb:0xff17354a);round(c,new RectF(x+22,y+20,x+74,y+54),14,open?0xff16a085:0xff547386);text(c,String.format("%02d",i+1),x+48,y+44,14,Color.WHITE,true,true);text(c,levels.get(i).title,x+22,y+91,24,open?0xff12324a:0xff6a8798,true,false);text(c,levels.get(i).subtitle,x+22,y+123,17,open?0xff527183:0xff49697c,false,false);int best=prefs.getInt("best."+i,0);text(c,open?(best>0?"★ Kỷ lục: "+best+" chuyến":"Sẵn sàng thử thách"):"Hoàn thành màn trước",x+22,y+173,14,open?0xff15967f:0xff6a8798,true,false);boat(c,x+278,y+150,.8f);}
        }
        void drawGame(Canvas c){gradient(c,0,0,W,H,0xffbce8f2,0xffeaf8f6);round(c,back,14,0xffffffff);text(c,"← Chọn màn",89,56,14,0xff35596b,true,true);text(c,"MÀN "+(level+1)+" / "+levels.size(),174,52,14,0xff527386,true,false);text(c,game.puzzle.title,174,84,25,0xff183f55,true,false);round(c,new RectF(840,24,1248,118),20,0xeaffffff);wrapped(c,game.puzzle.ruleText,860,50,365,20,0xff446779);
            gradient(c,0,170,W,410,0xff5ec4d5,0xff238eba);p.setColor(0xff68a950);c.drawRoundRect(new RectF(-45,150,425,620),80,80,p);c.drawRoundRect(new RectF(855,150,1325,620),80,80,p);p.setColor(0xff84c765);c.drawRoundRect(new RectF(-60,142,405,222),55,55,p);c.drawRoundRect(new RectF(875,142,1340,222),55,55,p);text(c,"BỜ KHỞI HÀNH",34,196,14,0xff315c40,true,false);text(c,"BỜ ĐÍCH",1138,196,14,0xff315c40,true,false);layout(c,false);layout(c,true);boat(c,game.boatRight?725:425,500,1f);
            round(c,new RectF(24,610,1256,736),26,0xfff7fcfd);text(c,game.message,48,651,17,0xff35596b,false,false);text(c,String.format("%02d",game.moves),792,655,25,0xff173f55,true,false);text(c,"CHUYẾN",788,679,14,0xff76919e,true,false);button(c,move,game.boatRight?"← QUA BỜ TRÁI":"QUA BỜ PHẢI →",0xff12a389,Color.WHITE);button(c,undo,"Hoàn tác",0xffeaf3f3,0xff35596b);button(c,reset,"Chơi lại",0xffeaf3f3,0xff35596b);button(c,hint,"Gợi ý",0xffffe7a8,0xff35596b);if(game.won)win(c);
        }
        void layout(Canvas c,boolean right){int count=0;for(int i=0;i<game.puzzle.people.length;i++)if((((game.rightMask>>i)&1)==1)==right)count++;int cols=count>6?3:2,k=0;for(int i=0;i<game.puzzle.people.length;i++)if((((game.rightMask>>i)&1)==1)==right){int x=(right?915:30)+(k%cols)*(right?105:118),y=225+(k/cols)*108;people[i]=new RectF(x,y,x+92,y+88);person(c,game.puzzle.people[i],people[i],(game.selected&(1<<i))!=0);k++;}}
        void person(Canvas c,Person who,RectF r,boolean selected){if(selected){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);p.setColor(0xffffd34e);c.drawOval(new RectF(r.left-5,r.top-5,r.right+5,r.bottom+5),p);p.setStyle(Paint.Style.FILL);}p.setColor(who.color|0xff000000);c.drawRoundRect(new RectF(r.left+20,r.top+35,r.left+72,r.top+73),18,18,p);p.setColor(light(who.color));c.drawCircle(r.left+46,r.top+25,21,p);p.setColor(0xff153a4d);c.drawCircle(r.left+39,r.top+22,2.5f,p);c.drawCircle(r.left+54,r.top+22,2.5f,p);text(c,who.shortName,r.left+46,r.top+62,12,Color.WHITE,true,true);text(c,who.name,r.left+46,r.top+87,12,0xff244b5d,true,true);}
        void win(Canvas c){p.setColor(0xc0051b2b);c.drawRect(0,0,W,H,p);round(c,new RectF(390,160,890,610),30,0xfff8fcfa);p.setColor(0xffffd45e);c.drawCircle(640,265,70,p);text(c,"★",640,292,72,Color.WHITE,true,true);text(c,"HOÀN THÀNH!",640,388,44,0xff173f55,true,true);text(c,"Bạn đã đưa mọi người qua sông an toàn",640,426,17,0xff587585,false,true);String stars=game.moves<=game.puzzle.parMoves?"★★★":game.moves<=game.puzzle.parMoves+3?"★★☆":"★☆☆";text(c,stars,640,482,34,0xfff4b835,true,true);text(c,game.moves+" chuyến • Mục tiêu "+game.puzzle.parMoves+" chuyến",640,512,14,0xff668391,true,true);button(c,new RectF(500,545,780,605),level+1<levels.size()?"MÀN TIẾP THEO →":"VỀ CHỌN MÀN",0xff12a389,Color.WHITE);}
        void boat(Canvas c,float x,float y,float s){p.setColor(0xffd8864e);Path path=new Path();path.moveTo(x,y);path.lineTo(x+130*s,y);path.lineTo(x+105*s,y+45*s);path.lineTo(x+25*s,y+45*s);path.close();c.drawPath(path,p);p.setColor(0xff6a402b);p.setStrokeWidth(6*s);c.drawLine(x+65*s,y,x+100*s,y-58*s,p);p.setColor(0xfff6e4b4);path.reset();path.moveTo(x+95*s,y-55*s);path.lineTo(x+95*s,y-8*s);path.lineTo(x+47*s,y-10*s);path.close();c.drawPath(path,p);}
        void button(Canvas c,RectF r,String s,int fill,int color){round(c,r,16,fill);text(c,s,r.centerX(),r.centerY()+5,14,color,true,true);}void round(Canvas c,RectF r,float radius,int color){p.setColor(color);p.setStyle(Paint.Style.FILL);c.drawRoundRect(r,radius,radius,p);}void text(Canvas c,String s,float x,float y,float size,int color,boolean bold,boolean center){p.setColor(color);p.setTextSize(size);p.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));p.setTextAlign(center?Paint.Align.CENTER:Paint.Align.LEFT);c.drawText(s,x,y,p);}void wrapped(Canvas c,String s,float x,float y,float width,float lh,int color){String line="";int row=0;for(String word:s.split(" ")){String next=line.length()==0?word:line+" "+word;p.setTextSize(14);if(p.measureText(next)>width){text(c,line,x,y+row++*lh,14,color,false,false);line=word;}else line=next;}text(c,line,x,y+row*lh,14,color,false,false);}void gradient(Canvas c,float x,float y,float w,float h,int a,int b){p.setShader(new LinearGradient(x,y,x,y+h,a,b,Shader.TileMode.CLAMP));c.drawRect(x,y,x+w,y+h,p);p.setShader(null);}int light(int color){return Color.rgb(Math.min(255,(int)(Color.red(color)*1.16)),Math.min(255,(int)(Color.green(color)*1.16)),Math.min(255,(int)(Color.blue(color)*1.16)));}
    }
}
